  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 用户表 - 必须包含 Token 字段用于存储和刷新用户凭证\nmodel User {\n  id             String   @id @default(cuid())\n  secondmeUserId String   @unique @map(\"secondme_user_id\")\n  accessToken    String   @map(\"access_token\")\n  refreshToken   String   @map(\"refresh_token\")\n  tokenExpiresAt DateTime @map(\"token_expires_at\")\n  name           String?\n  avatar         String?\n  email          String?\n  bio            String?\n\n  // 人生规划相关\n  lifePlans           LifePlan[]\n  knowledgeFrameworks KnowledgeFramework[]\n  notes               Note[]\n  matchesAsUser1      Match[]              @relation(\"User1Matches\")\n  matchesAsUser2      Match[]              @relation(\"User2Matches\")\n  conversations       Conversation[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"users\")\n}\n\n// 人生规划表 - 1/5/10年目标\nmodel LifePlan {\n  id          String   @id @default(cuid())\n  userId      String   @map(\"user_id\")\n  title       String\n  description String?\n  year        Int // 1, 5, 10\n  category    String // 职业、学习、健康、人际关系等\n  goals       Json // JSON格式的目标列表\n  milestones  Json // JSON格式的里程碑\n  progress    Float    @default(0) // 进度百分比\n  isPublic    Boolean  @default(false) @map(\"is_public\")\n  startDate   DateTime @map(\"start_date\")\n  endDate     DateTime @map(\"end_date\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([userId])\n  @@index([userId, year])\n  @@map(\"life_plans\")\n}\n\n// 知识框架表\nmodel KnowledgeFramework {\n  id          String  @id @default(cuid())\n  userId      String  @map(\"user_id\")\n  title       String\n  description String?\n  category    String // 领域分类\n  content     Json // 知识框架内容\n  tags        Json // 标签数组\n  isPublic    Boolean @default(false) @map(\"is_public\")\n  viewCount   Int     @default(0) @map(\"view_count\")\n  likeCount   Int     @default(0) @map(\"like_count\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([userId])\n  @@index([category])\n  @@map(\"knowledge_frameworks\")\n}\n\n// 用户匹配表（人生搭子）\nmodel Match {\n  id                String    @id @default(cuid())\n  user1Id           String    @map(\"user1_id\")\n  user2Id           String    @map(\"user2_id\")\n  matchScore        Float     @default(0) @map(\"match_score\")\n  matchReason       String?   @map(\"match_reason\") // 匹配原因\n  status            String    @default(\"pending\") // pending, matched, rejected\n  lastInteractionAt DateTime? @map(\"last_interaction_at\")\n\n  user1         User           @relation(\"User1Matches\", fields: [user1Id], references: [id], onDelete: Cascade)\n  user2         User           @relation(\"User2Matches\", fields: [user2Id], references: [id], onDelete: Cascade)\n  conversations Conversation[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([user1Id, user2Id])\n  @@index([user1Id])\n  @@index([user2Id])\n  @@index([user1Id, user2Id])\n  @@map(\"matches\")\n}\n\n// 对话记录表\nmodel Conversation {\n  id            String   @id @default(cuid())\n  userId        String   @map(\"user_id\")\n  matchId       String?  @map(\"match_id\")\n  type          String // personal, match\n  title         String?\n  lastMessage   String?\n  lastMessageAt DateTime @map(\"last_message_at\")\n  unreadCount   Int      @default(0) @map(\"unread_count\")\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  match    Match?    @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  messages Message[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([userId])\n  @@index([matchId])\n  @@map(\"conversations\")\n}\n\n// 消息表\nmodel Message {\n  id             String  @id @default(cuid())\n  conversationId String  @map(\"conversation_id\")\n  senderId       String  @map(\"sender_id\")\n  content        String\n  contentType    String  @default(\"text\") @map(\"content_type\") // text, image, file\n  isRead         Boolean @default(false) @map(\"is_read\")\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([conversationId])\n  @@index([senderId])\n  @@index([conversationId, createdAt])\n  @@map(\"messages\")\n}\n\n// 笔记表\nmodel Note {\n  id       String  @id @default(cuid())\n  userId   String  @map(\"user_id\")\n  title    String\n  content  String\n  type     String // 规划记录, 学习反思, 知识框架, 交流记录\n  tags     Json // 标签数组\n  isPublic Boolean @default(false) @map(\"is_public\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([userId])\n  @@index([userId, type])\n  @@map(\"notes\")\n}\n",
